import { useCallback, useEffect, useState } from "react";
import { ChevronRight, Columns2, Plus, X } from "lucide-react";
// @ts-ignore wailsjs bindings are generated by wails build
import { StartPty, StopPty } from "../../wailsjs/go/controllers/Terminal";
// @ts-ignore wailsjs bindings are generated by wails build
import { ListProjects } from "../../wailsjs/go/controllers/Projects";
import Terminal from "../components/terminal/Terminal";
import { useT } from "../lib/i18n";

type Pane = {
  id: string;
  label: string;
  kind: string;
  project?: string;
};

type Tab = {
  id: string;
  panes: Pane[];
  active: number;
};

let nextTab = 0;
let nextPaneLabel = 0;

export default function TerminalPage() {
  const t = useT();
  const [tabs, setTabs] = useState<Tab[]>([]);
  const [activeTab, setActiveTab] = useState(0);
  const [projects, setProjects] = useState<string[]>([]);
  const [kind, setKind] = useState("powershell");

  useEffect(() => {
    ListProjects().then((list: Array<{ name: string }>) => {
      setProjects((list ?? []).map((p) => p.name));
    }).catch(() => { /* pre-startup */ });
  }, []);

  const spawnPane = useCallback(
    async (project?: string): Promise<Pane | null> => {
      try {
        const sessionId = await StartPty({ kind, project: project || "", cols: 80, rows: 24 });
        nextPaneLabel++;
        const label = project ? `${kind}/${project}` : `${kind} #${nextPaneLabel}`;
        return { id: sessionId, label, kind, project };
      } catch {
        return null;
      }
    },
    [kind],
  );

  const openNewTab = useCallback(
    async (project?: string) => {
      const pane = await spawnPane(project);
      if (!pane) return;
      const tab: Tab = { id: `tab-${nextTab++}`, panes: [pane], active: 0 };
      setTabs((current) => {
        setActiveTab(current.length);
        return [...current, tab];
      });
    },
    [spawnPane],
  );

  const splitCurrent = useCallback(async () => {
    const pane = await spawnPane();
    if (!pane) return;
    setTabs((current) =>
      current.map((tab, i) =>
        i === activeTab ? { ...tab, panes: [...tab.panes, pane], active: tab.panes.length } : tab,
      ),
    );
  }, [activeTab, spawnPane]);

  const closePane = useCallback((tabIdx: number, paneIdx: number) => {
    setTabs((current) => {
      const tab = current[tabIdx];
      if (!tab) return current;
      const pane = tab.panes[paneIdx];
      if (pane) StopPty(pane.id).catch(() => { /* already dead */ });
      const remaining = tab.panes.filter((_, i) => i !== paneIdx);
      if (remaining.length === 0) {
        const next = current.filter((_, i) => i !== tabIdx);
        setActiveTab(Math.max(0, tabIdx - 1));
        return next;
      }
      return current.map((tb, i) =>
        i === tabIdx ? { ...tb, panes: remaining, active: Math.min(tb.active, remaining.length - 1) } : tb,
      );
    });
  }, []);

  // Auto-open first tab.
  useEffect(() => {
    if (tabs.length === 0) {
      void openNewTab();
    }
  }, [tabs.length, openNewTab]);

  // Ctrl+T new tab, Ctrl+W close pane.
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (!event.ctrlKey) return;
      if (event.key === "t") {
        event.preventDefault();
        void openNewTab();
      } else if (event.key === "w") {
        event.preventDefault();
        const tab = tabs[activeTab];
        if (tab) closePane(activeTab, tab.active);
      }
    };
    window.addEventListener("keydown", onKey, true);
    return () => window.removeEventListener("keydown", onKey, true);
  }, [tabs, activeTab, openNewTab, closePane]);

  const tab = tabs[activeTab];
  if (!tab) {
    return <div className="flex h-full items-center justify-center text-sm text-white/40">{t("common.loading")}</div>;
  }

  return (
    <div className="flex h-full flex-col gap-1.5">
      {/* Toolbar */}
      <div className="flex items-center gap-2 px-1 text-xs">
        <select className="input py-0.5 text-xs" value={kind} onChange={(e) => setKind(e.target.value)} aria-label="Terminal type">
          <option value="powershell">PowerShell</option>
          <option value="cmd">CMD</option>
          <option value="gitbash">Git Bash</option>
        </select>
        <select
          className="input py-0.5 text-xs"
          value=""
          onChange={(e) => e.target.value && void openNewTab(e.target.value)}
          aria-label="Project"
        >
          <option value="">{t("terminal.newTab")}</option>
          {projects.map((name) => (
            <option key={name} value={name}>{name}</option>
          ))}
        </select>
        <button
          type="button"
          onClick={() => void openNewTab()}
          title="Ctrl+T"
          className="flex items-center gap-1 rounded border border-white/10 bg-white/5 px-2 py-1 text-white/70 hover:bg-white/10"
        >
          <Plus className="h-3 w-3" /> {t("terminal.tab")}
        </button>
        <button
          type="button"
          onClick={() => void splitCurrent()}
          className="flex items-center gap-1 rounded border border-white/10 bg-white/5 px-2 py-1 text-white/70 hover:bg-white/10"
        >
          <Columns2 className="h-3 w-3" /> {t("terminal.split")}
        </button>
      </div>

      {/* Tab strip */}
      <div className="flex items-center gap-0.5 overflow-x-auto border-b border-white/10 pb-1">
        {tabs.map((tb, i) => (
          <button
            key={tb.id}
            type="button"
            onClick={() => setActiveTab(i)}
            className={`group flex items-center gap-1.5 rounded-t px-3 py-1.5 text-xs whitespace-nowrap transition-colors ${
              i === activeTab ? "bg-white/10 text-white" : "text-white/50 hover:bg-white/5"
            }`}
          >
            <ChevronRight className="h-2.5 w-2.5 opacity-40" />
            {tb.panes[tb.active]?.label ?? `Tab ${i + 1}`}
            {tb.panes.length > 1 && <span className="text-[9px] text-white/30">×{tb.panes.length}</span>}
            <span
              role="button"
              tabIndex={-1}
              onClick={(e) => {
                e.stopPropagation();
                tb.panes.forEach((_, pi) => closePane(i, pi));
              }}
              className="ml-1 rounded p-0.5 opacity-0 transition-opacity group-hover:opacity-60 hover:bg-white/20 hover:opacity-100"
            >
              <X className="h-3 w-3" />
            </span>
          </button>
        ))}
      </div>

      {/* Terminal area: CSS flex splits */}
      <div className="flex min-h-0 flex-1 gap-1 overflow-hidden rounded-lg border border-white/10 bg-[#171717]">
        {tab.panes.map((pane, pi) => (
          <div
            key={pane.id}
            className="group relative min-w-0 flex-1 border-r border-white/10 last:border-r-0"
          >
            <Terminal sessionId={pane.id} onExit={() => closePane(activeTab, pi)} />
            {tab.panes.length > 1 && (
              <button
                type="button"
                onClick={() => closePane(activeTab, pi)}
                className="absolute right-2 top-2 z-10 rounded border border-white/20 bg-black/60 p-1 text-white/60 opacity-0 transition-opacity group-hover:opacity-100 hover:text-white"
              >
                <X className="h-3 w-3" />
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}
